/* ===== FIX PATCH (PRE-2 clean targets & bank consistency) ===== */
(function(){
  function fix(DATA){
    try{
      var map = DATA.ITEMS || {};

      /* ===== 1. p2_23 修正（誤文削除） ===== */
      if(map["p2_23"]){
        map["p2_23"].targets = [
          "The teacher told us to be quiet.",
          "The teacher asked us to be quiet."
        ];
      }

      /* ===== 2. p2_22 語順改善 ===== */
      if(map["p2_22"]){
        map["p2_22"].targets = [
          "I will send you the details by email.",
          "I'll send you the details by email.",
          "I will send the details to you by email."
        ];
      }

      /* ===== 3. 関係代名詞：bank不足修正 ===== */
      [
        "pre2_rel_03",
        "pre2_rel_06",
        "pre2_rel_07",
        "pre2_rel_08",
        "pre2_rel_09"
      ].forEach(function(id){
        if(map[id] && map[id].bank){
          if(!map[id].bank.includes("that")){
            map[id].bank.push("that");
          }
          if(!map[id].bank.includes("which")){
            map[id].bank.push("which");
          }
        }
      });

      /* ===== 4. スマート引用符統一 ===== */
      Object.keys(map).forEach(function(id){
        var item = map[id];
        if(!item.targets) return;

        item.targets = item.targets.map(function(s){
          return s
            .replace(/[’‘]/g, "'")   // ← 重要
            .replace(/\s+/g, " ")
            .trim();
        });
      });

    }catch(e){
      console.warn("FIX PATCH failed", e);
    }
  }

  if(typeof DATA !== "undefined"){
    fix(DATA);
  }else{
    document.addEventListener("DOMContentLoaded", function(){
      if(typeof DATA !== "undefined") fix(DATA);
    });
  }
})();
